  type RawReviewSection,
} from './fixtures.ts'
import type { WorkerResult } from '../../contracts/workflow/v1.ts'

type InternalEvent = { sequence: number; time: string; node: string; status: string; message: string }
type Task = { node_id: string; error: string | null; interrupts: object[]; result: object | null }

function writeJson(path: string, value: unknown) {
  writeFileSync(path, `${JSON.stringify(value, null, 2)}\n`)
}

function receipt(node: string, runDir: string, sessionId: string, requestedAt: string) {
  return {
    node_id: node, session_id: sessionId, launch_token: launchToken(node),
    plan_digest: 'd'.repeat(64), worktree: join(runDir, `worktree-${node}`), base_commit: BASE_COMMIT,
    status: 'attached_session_available', attempt: 1, launcher_invocations: 1, launch_requested_at: requestedAt,
    background_id: backgroundId(node), observed_state: 'done', native_started_at: Date.parse(requestedAt),
  }
}

/** One verification packet in the `workflow/checks.py` layout; returns its registry entry. */
function writePacket(runDir: string, phase: 'worker' | 'candidate', node: string, attempt: number, result: WorkerResult, files: ArtifactFile[], gate: { status: string; reasons: string[]; deferred_checks?: string[] }) {
  const directory = join(runDir, 'verification', phase, node, String(attempt))
  const artifactsDir = join(directory, 'artifacts')
  mkdirSync(artifactsDir, { recursive: true })
  const artifactPaths: Record<string, string> = {}
  for (const file of files) {
    const destination = join(artifactsDir, file.artifact_id)
    writeFileSync(destination, file.content)
    artifactPaths[file.artifact_id] = destination
  }
  const worktree = join(directory, 'worktree')
  const expected = { run_id: result.run_id, node_id: node, attempt, base_commit: BASE_COMMIT, output_commit: result.output_commit ?? BASE_COMMIT, verification_cwd: worktree }
  // The immutable capture never carries `deferred_checks`; the adapter derives them from the gate when serving.
  const capture: Omit<WorkerResult, 'deferred_checks'> & { deferred_checks?: unknown } = { ...result }
  delete capture.deferred_checks
  const packet = {
    phase, expected,
    result: { ...capture, checks: capture.checks.map(check => ({ ...check, cwd: worktree })) },
    evidence: {
      version: '1.0.0', policy_sha256: 'e'.repeat(64), run_id: result.run_id, node_id: node, attempt, output_commit: expected.output_commit,
      checks: result.checks.map((_check, index) => ({ id: `check-${index}`, worker_check_index: index, tests: null, scenarios: [] })),
    },
    artifact_root: artifactsDir, artifact_paths: artifactPaths,
    capture_errors: gate.reasons, effective_commands: result.checks.map(check => check.command.split(' ')), gate,
  }
  const packetPath = join(directory, 'packet.json')
  writeJson(packetPath, packet)
  const relative = `verification/${phase}/${node}/${attempt}/packet.json`
  return { phase, node_id: node, attempt, path: relative, sha256: sha256(Buffer.from(`${JSON.stringify(packet, null, 2)}\n`)) }
}

type RunOptions = {
  createdAt: string; updatedAt: string; definitionNodes: typeof GRAPH_NODES; values: Record<string, unknown>; next: string[]; tasks: Task[]; events: InternalEvent[]
  packets: (runDir: string) => object[]
  /** Export version; 1.2.0 (the default) carries the `review` and `inputs` sections, 1.0.0 neither, 1.3.0 also pins the lane selection, 1.4.0 the reviewer set. */
  version?: '1.0.0' | '1.2.0' | '1.3.0' | '1.4.0'
  /** The reviewers the plan pins (`plan.reviewers`, export 1.4.0) in declared order; a plan without them has the single default reviewer. */
  reviewers?: readonly string[]
  /** The selected lanes the plan pins (`plan.nodes`, and `plan.workers` from 1.3.0); the two-lane runs predate the selection. */
  lanes?: readonly string[]
  /** The pinned definition's name (the registered workflow's name, so an unchanged graph hashes to the current revision). */
  definitionName?: string
  review?: RawReviewSection | null
  inputs?: RawInputsSection | null
  /** Content of `<run>/review.diff`, the diff the reviewer saw. */
  diff?: string
}

function writeRun(runsRoot: string, repository: string, runId: string, options: RunOptions) {
  const runDir = join(runsRoot, runId)
  mkdirSync(runDir, { recursive: true })
  const inputs = options.inputs ?? null
  const version = options.version ?? '1.2.0'
  const lanes = options.lanes ?? ['ui', 'adapter']
  const pinnedTask = (lane: string) => inputs?.workers[lane]?.task ?? (lane === 'ui' ? uiTask(leakFor(runsRoot, runId)) : lane === 'adapter' ? adapterTask() : docsTask())
  const plan = {
    run_id: runId, repository, base_commit: BASE_COMMIT, allow_edits: true,
    nodes: Object.fromEntries(lanes.map(lane => [lane, { worktree: join(runDir, `worktree-${lane}`), task: pinnedTask(lane), session_id: LANE_SESSIONS[lane], observed_start_commit: BASE_COMMIT }])),
    ...(version === '1.3.0' || version === '1.4.0' ? { workers: [...lanes], excluded_workers: inputs?.excluded_workers ?? [] } : {}),
    ...(options.reviewers ? { reviewers: options.reviewers.map(reviewer => ({ reviewer_id: reviewer, prompt: `Review the candidate as the ${reviewer} reviewer.` })) } : {}),
    mode: 'live', policy_sha256: 'e'.repeat(64), created_at: options.createdAt, source_branch: inputs?.source_branch ?? 'feature/synthetic',
    ...(inputs === null || inputs.automatic !== null ? { automatic: inputs?.automatic ?? { worker_timeout_seconds: 14400, review_timeout_seconds: 1800 } } : {}),
  }
  writeJson(join(runDir, 'plan.json'), plan)
  writeFileSync(join(runDir, 'events.jsonl'), options.events.map(event => JSON.stringify(event)).join('\n') + '\n')
  if (options.diff !== undefined) writeFileSync(join(runDir, 'review.diff'), options.diff)
  const packets = options.packets(runDir)
  const state = {
    version, run_id: runId, base_commit: BASE_COMMIT, created_at: options.createdAt,
    definition: { name: options.definitionName ?? WORKFLOW_NAME, nodes: options.definitionNodes },
    values: { run_id: runId, ...options.values }, next: options.next, tasks: options.tasks, events: options.events,
    verification_packets: packets, updated_at: options.updatedAt,
    ...(version !== '1.0.0' ? { review: options.review ?? null, inputs } : {}),
  }
  writeJson(join(runDir, 'run-state.json'), state)
  return runDir
}

/** A real absolute path under the run directory that the raw seeded texts name; the adapter must redact it. */
function leakFor(runsRoot: string, runId: string): string {
  return join(runsRoot, runId, 'worktree-ui', 'test-results')
}

const internalEvent = (sequence: number, time: string, node: string, status: string, message: string): InternalEvent => ({ sequence, time, node, status, message })

/** Seeds registry + runs under `root`; returns the registry path for MD_MANAGER_PROJECTS_CONFIG. */
export function seedCandidate(root: string): string {
  const repository = join(root, 'repository')
  const runsRoot = join(root, 'runs', WORKFLOW_ID)
  const emptyRunsRoot = join(root, 'runs', EMPTY_WORKFLOW_ID)
  const lanesRunsRoot = join(root, 'runs', LANES_WORKFLOW_ID)
  const reviewersRunsRoot = join(root, 'runs', REVIEWERS_WORKFLOW_ID)
  mkdirSync(repository, { recursive: true })
  mkdirSync(runsRoot, { recursive: true })
  mkdirSync(emptyRunsRoot, { recursive: true })
  mkdirSync(lanesRunsRoot, { recursive: true })
  mkdirSync(reviewersRunsRoot, { recursive: true })

  const packetSet = (runDir: string, phases: { phase: 'worker' | 'candidate'; node: string; attempt: number; result: WorkerResult; blocked?: string }[]) =>
    phases.map(entry => writePacket(runDir, entry.phase, entry.node, entry.attempt, entry.result, LANE_ARTIFACTS[entry.node],
      entry.blocked ? { status: 'blocked', reasons: [entry.blocked] }
        // Seeded evidence receipts are `check-<index>`, so a deferred check is named by its executed index.
        : { status: 'passed', reasons: [], ...(entry.result.deferred_checks ? { deferred_checks: entry.result.deferred_checks.map(check => `check-${check.check_index}`) } : {}) }))
  const fullPackets = (runId: string, runDir: string) => packetSet(runDir, [
    { phase: 'worker', node: 'ui', attempt: 1, result: uiResult(runId) },
    { phase: 'worker', node: 'adapter', attempt: 1, result: adapterResult(runId, false) },
    { phase: 'candidate', node: 'ui', attempt: 1, result: uiResult(runId) },
    { phase: 'candidate', node: 'adapter', attempt: 1, result: adapterResult(runId, false) },
  ])
  const reviewedValues = (runId: string, requestedAt: string) => ({
    ui: receipt('ui', join(runsRoot, runId), UI_SESSION, requestedAt), adapter: receipt('adapter', join(runsRoot, runId), ADAPTER_SESSION, requestedAt),
    snapshots: { ui: OUTPUT_COMMIT_UI, adapter: OUTPUT_COMMIT_ADAPTER },
    ui_packet: 'verification/worker/ui/1/packet.json', adapter_packet: 'verification/worker/adapter/1/packet.json',
    bundle: { run_id: runId, base_commit: BASE_COMMIT, candidate_commit: CANDIDATE_COMMIT, policy_sha256: 'e'.repeat(64) },
  })
  const launchEvents = (time: string) => [
    internalEvent(1, time, 'ui', 'running', 'Launching or reconciling the exact native session'),
    internalEvent(2, time, 'adapter', 'running', 'Launching or reconciling the exact native session'),
  ]

  writeRun(runsRoot, repository, RUN_SUCCEEDED, {
    createdAt: T0, updatedAt: T3, definitionNodes: PINNED_NODES,
    values: {
      ...reviewedValues(RUN_SUCCEEDED, T0),
      review: { run_id: RUN_SUCCEEDED, verdict: 'approved', independent: true, reviewer: 'synthetic-reviewer', findings: [] },
      approved_bundle: 'f'.repeat(64), integrated_commit: CANDIDATE_COMMIT,
    },
    next: [], tasks: [],
    events: [
      ...launchEvents(T0),
      internalEvent(3, T1, 'freeze', 'succeeded', 'Captured both worker snapshots'),
      internalEvent(4, T2, 'verify_ui', 'succeeded', 'UI verification passed'),
      internalEvent(5, T2, 'verify_adapter', 'succeeded', 'Adapter verification passed'),
      internalEvent(6, T3, 'review', 'approved', 'Independent reviewer approved the candidate'),
      internalEvent(7, T3, 'integrate', 'succeeded', 'Fast-forwarded the feature branch'),
    ],
    packets: runDir => fullPackets(RUN_SUCCEEDED, runDir),
    review: rawReviewSection(RUN_SUCCEEDED, leakFor(runsRoot, RUN_SUCCEEDED)),
    inputs: rawInputsSection(RUN_SUCCEEDED, leakFor(runsRoot, RUN_SUCCEEDED)),
    diff: REVIEW_DIFF,
  })

  writeRun(runsRoot, repository, RUN_FAILED, {
    createdAt: T1, updatedAt: T2, definitionNodes: GRAPH_NODES,
    values: {
      ui: receipt('ui', join(runsRoot, RUN_FAILED), UI_SESSION, T1), adapter: receipt('adapter', join(runsRoot, RUN_FAILED), ADAPTER_SESSION, T1),
      snapshots: { ui: OUTPUT_COMMIT_UI, adapter: OUTPUT_COMMIT_ADAPTER },
      ui_packet: 'verification/worker/ui/1/packet.json',
    },
    next: ['verify_adapter'],
    tasks: [{ node_id: 'verify_adapter', error: 'Injected gate failure: adapter verification attempt 1 was blocked by the configured failure drill', interrupts: [], result: null }],
    events: [
      ...launchEvents(T1),
      internalEvent(3, T2, 'freeze', 'succeeded', 'Captured both worker snapshots'),
      internalEvent(4, T2, 'verify_ui', 'succeeded', 'UI verification passed'),
      internalEvent(5, T2, 'verify_adapter', 'failed', 'Injected gate failure (failure drill); checks preserved'),
    ],
    packets: runDir => packetSet(runDir, [
      { phase: 'worker', node: 'ui', attempt: 1, result: uiResult(RUN_FAILED) },
      { phase: 'worker', node: 'adapter', attempt: 1, result: adapterResult(RUN_FAILED, true), blocked: 'Injected gate failure (failure drill)' },
    ]),
    review: null,
    inputs: rawInputsSection(RUN_FAILED, leakFor(runsRoot, RUN_FAILED)),
  })

  writeRun(runsRoot, repository, RUN_AWAITING, {
    createdAt: T2, updatedAt: T3, definitionNodes: GRAPH_NODES,
    values: reviewedValues(RUN_AWAITING, T2),
    next: ['review'],
    tasks: [{ node_id: 'review', error: null, interrupts: [{ kind: 'independent_review', message: 'Independent review required before integration' }], result: null }],
    events: [
      ...launchEvents(T2),
      internalEvent(3, T3, 'freeze', 'succeeded', 'Captured both worker snapshots'),
      internalEvent(4, T3, 'candidate', 'succeeded', 'Combined candidate checks passed'),
      internalEvent(5, T3, 'review', 'awaiting_approval', 'Independent review required before integration'),
    ],
    packets: runDir => fullPackets(RUN_AWAITING, runDir),
    review: null,
    inputs: rawInputsSection(RUN_AWAITING, leakFor(runsRoot, RUN_AWAITING)),
  })

  // The print-mode reviewer blocked this candidate: review.json holds the verdict, the graph task the error.
  writeRun(runsRoot, repository, RUN_BLOCKED, {
    createdAt: T1, updatedAt: T3, definitionNodes: GRAPH_NODES,
    values: reviewedValues(RUN_BLOCKED, T1),
    next: [],
    tasks: [{ node_id: 'review', error: `${BLOCKED_MESSAGE}; see ${join(runsRoot, RUN_BLOCKED, 'review.json')}`, interrupts: [], result: null }],
    events: [
      ...launchEvents(T1),
      internalEvent(3, T2, 'freeze', 'succeeded', 'Captured both worker snapshots'),
      internalEvent(4, T2, 'verify_ui', 'succeeded', 'UI verification passed'),
      internalEvent(5, T2, 'verify_adapter', 'succeeded', 'Adapter verification passed'),
      internalEvent(6, T2, 'candidate', 'succeeded', 'Combined candidate checks passed'),
      internalEvent(7, T3, 'review', 'running', 'Launching the print-mode reviewer'),
      internalEvent(8, T3, 'review', 'blocked', BLOCKED_MESSAGE),
    ],
    packets: runDir => packetSet(runDir, [
      { phase: 'worker', node: 'ui', attempt: 1, result: uiDeferredResult(RUN_BLOCKED) },
      { phase: 'worker', node: 'adapter', attempt: 1, result: adapterResult(RUN_BLOCKED, false) },
      { phase: 'candidate', node: 'ui', attempt: 1, result: uiResult(RUN_BLOCKED) },
      { phase: 'candidate', node: 'adapter', attempt: 1, result: adapterResult(RUN_BLOCKED, false) },
    ]),
    review: rawReviewSection(RUN_BLOCKED, leakFor(runsRoot, RUN_BLOCKED)),
    inputs: rawInputsSection(RUN_BLOCKED, leakFor(runsRoot, RUN_BLOCKED)),
  })

  // Integrated before review results and run inputs were exported: a 1.0.0 export whose `values.review` is never mined.
  writeRun(runsRoot, repository, RUN_LEGACY, {
    createdAt: T0, updatedAt: T2, definitionNodes: GRAPH_NODES,
    values: {
      ...reviewedValues(RUN_LEGACY, T0),
      review: { run_id: RUN_LEGACY, verdict: 'approved', independent: true, reviewer: 'synthetic-reviewer', findings: [] },
      approved_bundle: 'f'.repeat(64), integrated_commit: CANDIDATE_COMMIT,
    },
    next: [], tasks: [],
    events: [
      ...launchEvents(T0),
      internalEvent(3, T1, 'freeze', 'succeeded', 'Captured both worker snapshots'),
      internalEvent(4, T1, 'verify_ui', 'succeeded', 'UI verification passed'),
      internalEvent(5, T1, 'verify_adapter', 'succeeded', 'Adapter verification passed'),
      internalEvent(6, T2, 'review', 'approved', 'Review accepted (recorded before review results were exported)'),
      internalEvent(7, T2, 'integrate', 'succeeded', 'Fast-forwarded the feature branch'),
    ],
    packets: runDir => fullPackets(RUN_LEGACY, runDir),
    version: '1.0.0',
  })

  // ---- lanes-flow: 1.3.0 exports of runs whose lanes come from configuration (`ui`, `adapter`, `docs`) ----

  /** Per-lane state as the plan-driven pipeline keeps it, up to the verified candidate: receipts under `lanes`, packet paths under `packets`. */
  const laneCandidateValues = (runsRoot: string, runId: string, lanes: readonly string[], requestedAt: string) => ({
    lanes: Object.fromEntries(lanes.map(lane => [lane, receipt(lane, join(runsRoot, runId), LANE_SESSIONS[lane], requestedAt)])),
    snapshots: Object.fromEntries(lanes.map(lane => [lane, LANE_OUTPUT_COMMITS[lane]])),
    packets: Object.fromEntries(lanes.map(lane => [lane, `verification/worker/${lane}/1/packet.json`])),
    bundle: { run_id: runId, base_commit: BASE_COMMIT, candidate_commit: CANDIDATE_COMMIT, policy_sha256: 'e'.repeat(64) },
  })
  /** A configured run that was reviewed, approved and integrated. */
  const laneValues = (runId: string, lanes: readonly string[], requestedAt: string, runsRoot = lanesRunsRoot) => ({
    ...laneCandidateValues(runsRoot, runId, lanes, requestedAt),
    review: { run_id: runId, verdict: 'approved', independent: true, reviewer: 'synthetic-reviewer', findings: [] },
    approved_bundle: 'f'.repeat(64), integrated_commit: CANDIDATE_COMMIT,
  })
  const lanePackets = (runId: string, runDir: string, lanes: readonly string[]) => packetSet(runDir, lanes.flatMap(lane => [
    { phase: 'worker' as const, node: lane, attempt: 1, result: laneResult(lane, runId) },
    { phase: 'candidate' as const, node: lane, attempt: 1, result: laneResult(lane, runId) },
  ]))
  const laneEvents = (lanes: readonly string[], start: string, extra: InternalEvent[] = []): InternalEvent[] => {
    const events: InternalEvent[] = []
    const push = (time: string, node: string, status: string, message: string) => events.push(internalEvent(events.length + 1, time, node, status, message))
    for (const lane of lanes) push(start, lane, 'running', 'Launching or reconciling the exact native session')
    for (const event of extra) push(event.time, event.node, event.status, event.message)
    push(T2, 'freeze', 'succeeded', `Captured ${lanes.length === 1 ? 'the' : 'every'} worker snapshot`)
    for (const lane of lanes) push(T2, `verify_${lane}`, 'succeeded', `${lane} verification passed`)
    push(T2, 'candidate', 'succeeded', 'Combined candidate checks passed')
    push(T3, 'review', 'approved', 'Independent reviewer approved the candidate')
    push(T3, 'integrate', 'succeeded', 'Fast-forwarded the feature branch')
    return events
  }

  writeRun(lanesRunsRoot, repository, RUN_THREE_LANES, {
    createdAt: T1, updatedAt: T3, definitionNodes: THREE_LANE_NODES, definitionName: LANES_WORKFLOW_NAME, version: '1.3.0', lanes: THREE_LANES,
    values: laneValues(RUN_THREE_LANES, THREE_LANES, T1),
    next: [], tasks: [],
    events: laneEvents(THREE_LANES, T1),
    packets: runDir => lanePackets(RUN_THREE_LANES, runDir, THREE_LANES),
    review: rawReviewSection(RUN_THREE_LANES, leakFor(lanesRunsRoot, RUN_THREE_LANES)),
    inputs: rawInputsSection(RUN_THREE_LANES, leakFor(lanesRunsRoot, RUN_THREE_LANES)),
  })

  // Launched with `--workers docs`: the plan pins one lane and excludes the other two; the drill's lane was not selected.
  writeRun(lanesRunsRoot, repository, RUN_ONE_LANE, {
    createdAt: T2, updatedAt: T3, definitionNodes: ONE_LANE_NODES, definitionName: LANES_WORKFLOW_NAME, version: '1.3.0', lanes: ONE_LANE,
    values: laneValues(RUN_ONE_LANE, ONE_LANE, T2),
    next: [], tasks: [],
    events: laneEvents(ONE_LANE, T2, [internalEvent(0, T2, 'failure_drill', 'skipped', 'Failure drill skipped: its lane adapter was not selected')]),
    packets: runDir => lanePackets(RUN_ONE_LANE, runDir, ONE_LANE),
    review: rawReviewSection(RUN_ONE_LANE, leakFor(lanesRunsRoot, RUN_ONE_LANE)),
    inputs: rawInputsSection(RUN_ONE_LANE, leakFor(lanesRunsRoot, RUN_ONE_LANE)),
  })

  // ---- reviewers-flow: a feature declaring the reviewers `general` and `coverage` over the plain two-lane graph ----

  const reviewersLeak = (runId: string) => leakFor(reviewersRunsRoot, runId)
  const reviewerLaunchEvents = (): InternalEvent[] => [
    internalEvent(0, T2, 'review', 'running', 'Launching reviewer general over the shared review worktree'),
    internalEvent(0, T2, 'review', 'running', 'Launching reviewer coverage over the shared review worktree'),
  ]

  // Both reviewers' completion files were accepted: review.json holds the combined verdict and both entries.
  writeRun(reviewersRunsRoot, repository, RUN_TWO_REVIEWERS, {
    createdAt: T1, updatedAt: T3, definitionNodes: REVIEWERS_NODES, definitionName: REVIEWERS_WORKFLOW_NAME, version: '1.4.0', lanes: TWO_LANES, reviewers: TWO_REVIEWERS,
    values: {
      ...laneValues(RUN_TWO_REVIEWERS, TWO_LANES, T1, reviewersRunsRoot),
      review: {
        run_id: RUN_TWO_REVIEWERS, verdict: 'approved', independent: true, reviewer: 'synthetic-reviewer', findings: [],
        reviewers: TWO_REVIEWERS.map(reviewer => ({ reviewer_id: reviewer, session_id: `synthetic-${reviewer}`, verdict: 'approved', accepted_at: T3 })),
      },
    },
    next: [], tasks: [],
    events: laneEvents(TWO_LANES, T1, reviewerLaunchEvents()),
    packets: runDir => lanePackets(RUN_TWO_REVIEWERS, runDir, TWO_LANES),
    review: rawReviewSection(RUN_TWO_REVIEWERS, reviewersLeak(RUN_TWO_REVIEWERS)),
    inputs: rawInputsSection(RUN_TWO_REVIEWERS, reviewersLeak(RUN_TWO_REVIEWERS)),
  })

  // `coverage` blocked while `general` was still working: the run failed at the review node and `general` was stopped and superseded.
  writeRun(reviewersRunsRoot, repository, RUN_REVIEWER_BLOCKED, {
    createdAt: T2, updatedAt: T3, definitionNodes: REVIEWERS_NODES, definitionName: REVIEWERS_WORKFLOW_NAME, version: '1.4.0', lanes: TWO_LANES, reviewers: TWO_REVIEWERS,
    values: laneCandidateValues(reviewersRunsRoot, RUN_REVIEWER_BLOCKED, TWO_LANES, T2),
    next: [],
    tasks: [{ node_id: 'review', error: `${REVIEWER_BLOCKED_MESSAGE}; see ${join(reviewersRunsRoot, RUN_REVIEWER_BLOCKED, 'review.json')}`, interrupts: [], result: null }],
    events: (() => {
      const events: InternalEvent[] = []
      const push = (time: string, node: string, status: string, message: string) => events.push(internalEvent(events.length + 1, time, node, status, message))
      for (const lane of TWO_LANES) push(T2, lane, 'running', 'Launching or reconciling the exact native session')
      push(T2, 'freeze', 'succeeded', 'Captured every worker snapshot')
      for (const lane of TWO_LANES) push(T2, `verify_${lane}`, 'succeeded', `${lane} verification passed`)
      push(T2, 'candidate', 'succeeded', 'Combined candidate checks passed')
      for (const event of reviewerLaunchEvents()) push(event.time, event.node, event.status, event.message)
      push(T3, 'review', 'blocked', REVIEWER_BLOCKED_MESSAGE)
      return events
    })(),
    packets: runDir => lanePackets(RUN_REVIEWER_BLOCKED, runDir, TWO_LANES),
    review: rawReviewSection(RUN_REVIEWER_BLOCKED, reviewersLeak(RUN_REVIEWER_BLOCKED)),
    inputs: rawInputsSection(RUN_REVIEWER_BLOCKED, reviewersLeak(RUN_REVIEWER_BLOCKED)),
  })

  // Reviewed before the feature declared reviewers: a 1.3.0 export whose review section has no `reviewers` list.
  writeRun(reviewersRunsRoot, repository, RUN_LEGACY_REVIEWER, {
    createdAt: T0, updatedAt: T2, definitionNodes: REVIEWERS_NODES, definitionName: REVIEWERS_WORKFLOW_NAME, version: '1.3.0', lanes: TWO_LANES,
    values: laneValues(RUN_LEGACY_REVIEWER, TWO_LANES, T0, reviewersRunsRoot),
    next: [], tasks: [],
    events: laneEvents(TWO_LANES, T0),
    packets: runDir => lanePackets(RUN_LEGACY_REVIEWER, runDir, TWO_LANES),
    review: rawReviewSection(RUN_LEGACY_REVIEWER, reviewersLeak(RUN_LEGACY_REVIEWER)),
    inputs: rawInputsSection(RUN_LEGACY_REVIEWER, reviewersLeak(RUN_LEGACY_REVIEWER)),
  })

  const registry = {
    version: 1,
    projects: [
      {
        project_id: PROJECT.project_id, name: PROJECT.name, repository,
        workflows: [
          { workflow_id: WORKFLOW_ID, runs_root: runsRoot, definition: { name: WORKFLOW_NAME, nodes: GRAPH_NODES } },
          { workflow_id: EMPTY_WORKFLOW_ID, runs_root: emptyRunsRoot, definition: { name: EMPTY_WORKFLOW_NAME, nodes: EMPTY_WORKFLOW_DEFINITION.nodes } },
          { workflow_id: LANES_WORKFLOW_ID, runs_root: lanesRunsRoot, definition: { name: LANES_WORKFLOW_NAME, nodes: THREE_LANE_NODES } },
          { workflow_id: REVIEWERS_WORKFLOW_ID, runs_root: reviewersRunsRoot, definition: { name: REVIEWERS_WORKFLOW_NAME, nodes: REVIEWERS_NODES } },
        ],
      },
      { project_id: EMPTY_PROJECT.project_id, name: EMPTY_PROJECT.name, repository, workflows: [] },
    ],
  }
  const configPath = join(root, 'projects.json')
  writeJson(configPath, registry)
  return configPath
}

import { defineConfig } from '@playwright/test'
import { execFileSync } from 'node:child_process'
import { cpSync, mkdirSync, mkdtempSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { ROOT_PREFIX, SKILL_LOCATIONS, verificationPhase } from './harness.ts'
import { seedCandidate } from './seed.ts'

/**
 * Dedicated configuration for the Projects viewer scenarios (`features/project-workflows/policy.json`).
 *
 * - Its own temporary root (skills fixtures for Pi/Claude and, in candidate mode, the seeded project
 *   registry and run directories) and its own dynamically chosen API/web ports, so it never touches live
 *   skills, live project storage or a developer's running servers. `global-teardown.ts` removes the root.
 * - `WORKFLOW_VERIFICATION_PHASE=worker` (default): the backend has no projects routes; specs mock only
 *   `/api/projects/**` with the explicit contract fixtures.
 * - `WORKFLOW_VERIFICATION_PHASE=candidate`: the real combined backend is started with the seeded registry;
 *   no project success responses are mocked.
 *
 * Playwright evaluates this module in the runner and again in every worker process; the root and ports are
 * prepared once and handed down through the environment.
 */
const phase = verificationPhase()

function freePort(): number {
  const script = "const s=require('net').createServer();s.listen(0,'127.0.0.1',()=>{process.stdout.write(String(s.address().port));s.close()})"
  return Number(execFileSync(process.execPath, ['-e', script], { encoding: 'utf8' }).trim())
}

function prepare(): { root: string; apiPort: number; webPort: number; projectsConfig: string | null } {
  const existing = process.env.MD_MANAGER_PROJECTS_TEST_ROOT
  if (existing) {
    return {
      root: existing,
      apiPort: Number(process.env.MD_MANAGER_API_PORT),
      webPort: Number(process.env.MD_MANAGER_WEB_PORT),
      projectsConfig: process.env.MD_MANAGER_PROJECTS_CONFIG || null,
    }
  }
  const root = mkdtempSync(join(tmpdir(), ROOT_PREFIX))
  const fixtures = fileURLToPath(new URL('../../fixtures/', import.meta.url))
  cpSync(join(fixtures, 'pi'), join(root, 'pi-personal'), { recursive: true })
  cpSync(join(fixtures, 'claude'), join(root, 'claude-personal'), { recursive: true })
  mkdirSync(join(root, 'pi-package', 'review'), { recursive: true })
  writeFileSync(join(root, 'pi-package', 'review', 'SKILL.md'), '# Package review skill\n\nInstalled by a package.\n')
  mkdirSync(join(root, 'claude-plugin', 'review'), { recursive: true })
  writeFileSync(join(root, 'claude-plugin', 'review', 'SKILL.md'), '# Plugin review skill\n\nInstalled by a plugin.\n')
  // pi-missing is configured but deliberately not created: an unavailable location, as in the root harness.
  const sources = { version: 1, locations: SKILL_LOCATIONS.map(({ id, source, label, directory, category }) => ({ id, source, label, path: join(root, directory), category })) }
  writeFileSync(join(root, 'sources.json'), `${JSON.stringify(sources, null, 2)}\n`)
  const projectsConfig = phase === 'candidate' ? seedCandidate(join(root, 'projects')) : null
  let apiPort = freePort()
  let webPort = freePort()
  while (webPort === apiPort) webPort = freePort()
  if (apiPort === webPort) apiPort = freePort()
  process.env.MD_MANAGER_PROJECTS_TEST_ROOT = root
  // The root skills helpers read this to locate the seeded location directories.
  process.env.MD_MANAGER_TEST_ROOT = root
  process.env.MD_MANAGER_CONFIG = join(root, 'sources.json')
  process.env.MD_MANAGER_API_PORT = String(apiPort)
  process.env.MD_MANAGER_WEB_PORT = String(webPort)
  process.env.WORKFLOW_VERIFICATION_PHASE = phase
  if (projectsConfig) process.env.MD_MANAGER_PROJECTS_CONFIG = projectsConfig
  else delete process.env.MD_MANAGER_PROJECTS_CONFIG
  return { root, apiPort, webPort, projectsConfig }
}

const { root, apiPort, webPort, projectsConfig } = prepare()
const baseURL = `http://127.0.0.1:${webPort}`

const apiEnv: Record<string, string> = {
  MD_MANAGER_CONFIG: join(root, 'sources.json'),
  MD_MANAGER_FIXTURE_ROOT: '',
  MD_MANAGER_API_PORT: String(apiPort),
  MD_MANAGER_WEB_PORT: String(webPort),
  WORKFLOW_VERIFICATION_PHASE: phase,
  ...(projectsConfig ? { MD_MANAGER_PROJECTS_CONFIG: projectsConfig } : {}),
}

export default defineConfig({
  testDir: '.',
  testMatch: '**/*.spec.ts',
  globalTeardown: './global-teardown.ts',
  outputDir: process.env.MD_MANAGER_PROJECTS_OUTPUT ?? join(process.cwd(), 'test-results', 'project-workflows'),
  workers: 1,
  fullyParallel: false,
  retries: 0,
  use: {
    baseURL,
    browserName: 'chromium',
    reducedMotion: 'reduce',
  },
  webServer: [
    {
      command: 'npm run start:api',
      url: `http://127.0.0.1:${apiPort}/api/entries`,
      env: apiEnv,
      reuseExistingServer: false,
      timeout: 30_000,
    },
    {
      command: 'npm run dev:web',
      url: baseURL,
      env: { MD_MANAGER_API_PORT: String(apiPort), MD_MANAGER_WEB_PORT: String(webPort) },
      reuseExistingServer: false,
      timeout: 30_000,
    },
  ],
})

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "Review completion signal v1.2.0",
  "description": "Written once by a native reviewer session to <run>/<node>.completion.json, where <node> is `review` for the default reviewer and `review-<reviewer_id>` for a reviewer declared in feature.json 2.1.0. The controller accepts it only when it validates here, its bindings match the run (run_id, that reviewer's node id, the launch_token from that reviewer's prompt, bundle SHA-256 and candidate commit from review-bundle.json) and the reviewer session is idle or done; a file whose node_id names another reviewer is rejected. Every declared reviewer must approve: a verdict of blocked, or any P0/P1 finding that is not resolved, from any reviewer ends the run and no reviewer is relaunched. 1.2.0: node_id follows `^review(-[a-z0-9-]{1,32})?$`. 1.1.0: a finding's `worker` is a lane id of the run (`^[a-z][a-z0-9-]{0,31}$`), `multiple` or `none`; the controller additionally rejects a lane id the run did not select. The legacy `both` is not accepted any more. Files spelling version 1.0.0 or 1.1.0 are still accepted under the same rules.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "version",
    "run_id",
    "node_id",
    "launch_token",
    "bundle_sha256",
    "candidate_commit",
    "verdict",
    "findings"
  ],
  "properties": {
    "version": {
      "enum": [
        "1.0.0",
        "1.1.0",
        "1.2.0"
      ]
    },
    "run_id": {
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$"
    },
    "node_id": {
      "type": "string",
      "pattern": "^review(-[a-z0-9-]{1,32})?$",
      "description": "`review` for the default reviewer, `review-<reviewer_id>` for a declared reviewer; the controller binds it to the reviewer the prompt named."
    },
    "launch_token": {
      "type": "string",
      "pattern": "^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$"
    },
    "bundle_sha256": {
      "type": "string",
      "pattern": "^[a-f0-9]{64}$"
    },
    "candidate_commit": {
      "type": "string",
      "pattern": "^[a-f0-9]{40}$"
    },
    "verdict": {
      "enum": [
        "approved",
        "blocked"
      ]
    },
    "findings": {
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "severity",
          "message",
          "disposition",
          "worker",
          "requirement"
        ],
        "properties": {
          "severity": {
            "enum": [
              "P0",
              "P1",
              "P2"
            ]
          },
          "message": {
            "type": "string",
            "minLength": 1
          },
          "disposition": {
            "enum": [
              "open",
              "resolved",
              "accepted"
            ]
          },
          "worker": {
            "description": "The lane whose assignment the finding concerns (one of the run's selected lane ids), `multiple` when it concerns several lanes, or `none` for cross-cutting/policy findings. Never `both` and never a fixed graph node name.",
            "type": "string",
            "pattern": "^(?!(?:review|candidate|handoff|approval|integrate|both)$)(?!(?:launch_|verify_|candidate_|review-))[a-z][a-z0-9-]{0,31}$"
          },
          "requirement": {
            "description": "A verbatim quote from that lane's task text that the finding relates to, or null when no single requirement applies. Consumers link a finding to its task only when the quote is found verbatim; nothing is inferred.",
            "type": [
              "string",
              "null"
            ],
            "minLength": 1
          }
        }
      }
    }
  }
}

// ---- Raw export sections (the shapes workflow/export_state.py 1.2.0, 1.3.0 and 1.4.0 write) --------------

export type RawFinding = {
  severity: 'P0' | 'P1' | 'P2'
  message: string
  disposition: 'open' | 'resolved' | 'accepted'
  /** A lane id, `multiple` or `none`; `both` is what two-lane exports recorded and is still accepted; null predates the field. */
  worker: string | null
  requirement: string | null
  /** Export 1.4.0: the id of the reviewer that raised the finding; absent before, when the one reviewer was `review`. */
  reviewer?: string
}
/**
 * How one reviewer of a 1.4.0 export ended, as `workflow/export_state.py` writes it (the contract's `REVIEWER_STATUSES`, mapped
 * from the controller's status file: `succeeded` and `accepted` both become `accepted`): `accepted` when its completion file
 * was accepted, `blocked` for its own block (a blocked verdict, an unresolved P0/P1, the deadline or a rejected file, the last
 * two with no verdict), `superseded` when it was stopped after another reviewer's block, `pending` when no verdict was recorded.
 */
export type RawReviewerStatus = 'accepted' | 'blocked' | 'superseded' | 'pending'
/**
 * One reviewer of a 1.4.0 export (PRD_PARALLEL_REVIEWERS section 4: id, transport, session id, verdict, findings, launch
 * and acceptance times, status). A reviewer that delivered no verdict (superseded, the deadline, a rejected file) has `verdict` null.
 */
export type RawReviewer = {
  reviewer_id: string
  transport: 'native' | 'print' | 'manual'
  session_id: string
  verdict: 'approved' | 'blocked' | null
  findings: RawFinding[]
  launched_at: string | null
  accepted_at: string | null
  status: RawReviewerStatus
}
export type RawReviewSection = {
  attempt: number
  transport: 'native' | 'print' | 'manual'
  /** `review.json`'s `reviewer`: the one session before 1.4.0, the declared reviewers' sessions joined with ", " from 1.4.0. */
  reviewer_session_id: string
  independent: true
  bundle_sha256: string
  candidate_commit: string
  /** The combined verdict: approved only when every reviewer approved and no reviewer left an unresolved P0/P1. */
  verdict: 'approved' | 'blocked'
  /** The union of every reviewer's findings, each tagged with `reviewer` from 1.4.0; one reviewer's untagged findings before. */
  findings: RawFinding[]
  reviewed_at: string
  diff: { path: 'review.diff'; sha256: string; bytes: number } | null
  /** Export 1.4.0 only, one entry per declared reviewer in declared order; absent before, when the adapter fills one entry named `review`. */
  reviewers?: RawReviewer[]
}
export type RawCheck = { id: string; kind: 'build' | 'typecheck' | 'unit' | 'integration' | 'contract' | 'browser'; argv: string[]; command: string; timeout_seconds: number; scenarios: { id: string; description: string }[] }
export type RawWorkerInput = {
  /** Any label since policy 1.2.0; `frontend` or `backend` before. */
  role: string
  /** Pinned per lane since policy 1.2.0 (export 1.3.0); absent in 1.2.0 exports, whose adapter derives it from the role. */
  required_check_kinds?: RawCheck['kind'][]
  task: string
  prompt: string | null
  owned_paths: string[]
  checks: RawCheck[]
  launch: { session_id: string | null; launch_token: string; launch_requested_at: string; native_started_at: number | null; observed_state: string | null; status: string; launcher_invocations: number; background_id: string | null } | null
  completion: { status: 'completed' | 'blocked'; summary: string; open_assumptions: string[] } | null
  handoff: { summary: string; open_assumptions: string[] } | null
  stop: { stopped: boolean; confirmed_at: string | null } | null
}
export type RawInputsSection = {
  feature: string
  policy_version: string
  base_commit: string
  source_branch: string | null
  mode: 'automatic' | 'manual'
  automatic: { finish: string; permission_mode: string; worker_timeout_seconds: number; review_timeout_seconds: number; reviewer_transport: 'native' | 'print' | null } | null
  setup: { argv: string[]; command: string; timeout_seconds: number }[]
  max_verification_attempts: number
  failure_drill: { node_id: string; phase: string; attempt: number } | null
  /** Export 1.3.0 only: the lanes the launch selected (pinned in `plan.workers`) and the declared lanes it left out. */
  selected_workers?: string[]
  excluded_workers?: string[]
  /** Keyed by lane id in policy order; a 1.3.0 export lists the selected lanes only. */
  workers: Record<string, RawWorkerInput>
}

/** Receipts store `+00:00` offsets; the adapter normalises them to a trailing Z. */
const offset = (iso: string) => iso.replace(/Z$/, '+00:00')
const zulu = (value: string) => (value.endsWith('+00:00') ? `${value.slice(0, -6)}Z` : value)

/** A finding both reviewers of the two-reviewer run raised independently: unioned, never merged, so it is listed twice. */
export const DUPLICATE_FINDING = 'The findings table drops the disposition column below 480px.'
export const COVERAGE_FINDING_UI = 'No browser scenario drives the reviewer filter while findings are grouped by worker.'
export const COVERAGE_FINDING_ADAPTER = 'The adapter unit tests never serve a superseded reviewer entry.'
export const BLOCKING_COVERAGE_FINDING = 'The two-reviewer browser scenario asserts nothing about the blocked run.'

/** The findings one reviewer of a two-reviewer run recorded (tagged with its id); the run's union keeps declared order. */
export function reviewerFindings(runId: string, reviewer: string): RawFinding[] {
  return reviewFindings(runId).filter(finding => finding.reviewer === reviewer)
}

/** The reviewer's findings for a run (the union of every reviewer's from 1.4.0); one message and one quote name a directory (redacted by the adapter). */
export function reviewFindings(runId: string, leak = PATH_TOKEN): RawFinding[] {
  if (runId === RUN_TWO_REVIEWERS) {
    // `general` then `coverage` in declared order; the first ui finding was raised by both and stays two findings.
    return [
      { severity: 'P2', message: DUPLICATE_FINDING, disposition: 'open', worker: 'ui', requirement: UI_QUOTE, reviewer: 'general' },
      { severity: 'P2', message: 'The review route re-reads the export on every request.', disposition: 'accepted', worker: 'adapter', requirement: ADAPTER_QUOTE, reviewer: 'general' },
      { severity: 'P2', message: DUPLICATE_FINDING, disposition: 'open', worker: 'ui', requirement: UI_QUOTE, reviewer: 'coverage' },
      { severity: 'P2', message: COVERAGE_FINDING_UI, disposition: 'open', worker: 'ui', requirement: null, reviewer: 'coverage' },
      { severity: 'P2', message: COVERAGE_FINDING_ADAPTER, disposition: 'accepted', worker: 'adapter', requirement: ADAPTER_QUOTE, reviewer: 'coverage' },
    ]
  }
  if (runId === RUN_REVIEWER_BLOCKED) {
    // Only `coverage` delivered findings: `general` was stopped once the block was recorded and left none.
    return [
      { severity: 'P1', message: BLOCKING_COVERAGE_FINDING, disposition: 'open', worker: 'ui', requirement: UI_QUOTE, reviewer: 'coverage' },
      { severity: 'P2', message: `Screenshots were written beside ${leak} instead of below it.`, disposition: 'resolved', worker: 'ui', requirement: uiPathQuote(leak), reviewer: 'coverage' },
    ]
  }
  if (runId === RUN_LEGACY_REVIEWER) {
    return [
      { severity: 'P2', message: 'The summary line paraphrases the disposition counts.', disposition: 'open', worker: 'ui', requirement: PARAPHRASED_QUOTE },
      { severity: 'P2', message: 'The review route re-reads the export on every request.', disposition: 'accepted', worker: 'adapter', requirement: ADAPTER_QUOTE },
    ]
  }
  if (runId === RUN_THREE_LANES) {
    // One finding per lane, one that concerns several lanes in the current vocabulary, one recorded with the
    // legacy `both` value (never written by a 1.3.0 controller, but accepted from exports), and one cross-cutting.
    return [
      { severity: 'P2', message: 'The findings table drops the disposition column below 480px.', disposition: 'open', worker: 'ui', requirement: UI_QUOTE },
      { severity: 'P2', message: 'The feature README lists the docs lane without its owned paths.', disposition: 'open', worker: 'docs', requirement: DOCS_QUOTE },
      { severity: 'P2', message: 'The review route re-reads the export on every request.', disposition: 'accepted', worker: 'adapter', requirement: ADAPTER_QUOTE },
      { severity: 'P2', message: 'The ui and docs lanes name the same check id differently in their tasks.', disposition: 'open', worker: 'multiple', requirement: null },
      { severity: 'P2', message: 'Both lanes duplicate the redaction regex in their tests.', disposition: 'accepted', worker: 'both', requirement: null },
      { severity: 'P2', message: 'The root Playwright suite is not part of the policy check set.', disposition: 'open', worker: 'none', requirement: null },
    ]
  }
  if (runId === RUN_ONE_LANE) {
    return [
      { severity: 'P2', message: 'The cheatsheet still shows the two-lane handoff flags.', disposition: 'resolved', worker: 'docs', requirement: DOCS_QUOTE },
      { severity: 'P2', message: 'The excluded lanes are not named in the run summary.', disposition: 'accepted', worker: 'none', requirement: null },
    ]
  }
  if (runId === RUN_BLOCKED) {
    return [
      { severity: 'P1', message: 'The inputs route still serves the worktree path of the adapter lane.', disposition: 'open', worker: 'adapter', requirement: ADAPTER_QUOTE },
      { severity: 'P2', message: 'Naming of the review panel props was inconsistent; fixed before the verdict.', disposition: 'resolved', worker: 'ui', requirement: null },
    ]
  }
  return [
    { severity: 'P2', message: 'The findings table drops the disposition column below 480px.', disposition: 'open', worker: 'ui', requirement: UI_QUOTE },
    { severity: 'P2', message: `Screenshots were written beside ${leak} instead of below it.`, disposition: 'open', worker: 'ui', requirement: uiPathQuote(leak) },
    { severity: 'P2', message: 'The summary line paraphrases the disposition counts.', disposition: 'open', worker: 'ui', requirement: PARAPHRASED_QUOTE },
    { severity: 'P2', message: 'The root Playwright suite is not part of the policy check set.', disposition: 'open', worker: 'none', requirement: null },
    { severity: 'P2', message: 'The review route re-reads the export on every request.', disposition: 'accepted', worker: 'adapter', requirement: ADAPTER_QUOTE },
    { severity: 'P2', message: 'Both lanes duplicate the redaction regex in their tests.', disposition: 'accepted', worker: 'both', requirement: null },
  ]
}

/** The export's `review` section for a run, or null for runs whose review was not reached or not exported. */
export function rawReviewSection(runId: string, leak = PATH_TOKEN): RawReviewSection | null {
  if (runId === RUN_SUCCEEDED) {
    return {
      attempt: 1, transport: 'native', reviewer_session_id: REVIEWER_SESSION, independent: true, bundle_sha256: BUNDLE_SHA256, candidate_commit: CANDIDATE_COMMIT,
      verdict: 'approved', findings: reviewFindings(runId, leak), reviewed_at: offset(T3),
      diff: { path: 'review.diff', sha256: sha256(REVIEW_DIFF), bytes: Buffer.byteLength(REVIEW_DIFF) },
    }
  }
  if (runId === RUN_BLOCKED) {
    return {
      attempt: 1, transport: 'print', reviewer_session_id: PRINT_REVIEWER_SESSION, independent: true, bundle_sha256: BUNDLE_SHA256, candidate_commit: CANDIDATE_COMMIT,
      verdict: 'blocked', findings: reviewFindings(runId, leak), reviewed_at: offset(T3), diff: null,
    }
  }
  if (runId === RUN_THREE_LANES || runId === RUN_ONE_LANE) {
    return {
      attempt: 1, transport: 'native', reviewer_session_id: REVIEWER_SESSION, independent: true, bundle_sha256: BUNDLE_SHA256, candidate_commit: CANDIDATE_COMMIT,
      verdict: 'approved', findings: reviewFindings(runId, leak), reviewed_at: offset(T3), diff: null,
    }
  }
  if (runId === RUN_TWO_REVIEWERS) {
    // Both completion files were accepted; the combined verdict is approved and the union carries both reviewer tags.
    const findings = reviewFindings(runId, leak)
    return {
      attempt: 1, transport: 'native', reviewer_session_id: JOINED_REVIEWER_SESSIONS, independent: true, bundle_sha256: BUNDLE_SHA256, candidate_commit: CANDIDATE_COMMIT,
      verdict: 'approved', findings, reviewed_at: offset(T3), diff: null,
      reviewers: TWO_REVIEWERS.map(reviewer => ({
        reviewer_id: reviewer, transport: 'native', session_id: REVIEWER_SESSIONS[reviewer], verdict: 'approved',
        findings: findings.filter(finding => finding.reviewer === reviewer), launched_at: offset(T2), accepted_at: offset(T3), status: 'accepted',
      })),
    }
  }
  if (runId === RUN_REVIEWER_BLOCKED) {
    // `coverage` blocked while `general` was still working: the run blocked at once, `general` was stopped and superseded, no relaunch.
    const findings = reviewFindings(runId, leak)
    return {
      attempt: 1, transport: 'native', reviewer_session_id: JOINED_REVIEWER_SESSIONS, independent: true, bundle_sha256: BUNDLE_SHA256, candidate_commit: CANDIDATE_COMMIT,
      verdict: 'blocked', findings, reviewed_at: offset(T3), diff: null,
      reviewers: [
        { reviewer_id: 'general', transport: 'native', session_id: GENERAL_REVIEWER_SESSION, verdict: null, findings: [], launched_at: offset(T2), accepted_at: null, status: 'superseded' },
        { reviewer_id: 'coverage', transport: 'native', session_id: COVERAGE_REVIEWER_SESSION, verdict: 'blocked', findings, launched_at: offset(T2), accepted_at: offset(T3), status: 'blocked' },
      ],
    }
  }
  if (runId === RUN_LEGACY_REVIEWER) {
    // A 1.3.0 export: one reviewer, no `reviewers` list and no `reviewer` tags; the adapter fills one entry named `review`.
    return {
      attempt: 1, transport: 'native', reviewer_session_id: LEGACY_REVIEWER_SESSION, independent: true, bundle_sha256: BUNDLE_SHA256, candidate_commit: CANDIDATE_COMMIT,
      verdict: 'approved', findings: reviewFindings(runId, leak), reviewed_at: offset(T2), diff: null,
    }
  }
  return null
}

export const UI_CHECKS: RawCheck[] = [
  { id: 'frontend-build', kind: 'build', argv: ['npm', 'run', 'build'], command: 'npm run build', timeout_seconds: 180, scenarios: [] },
  { id: 'frontend-unit', kind: 'unit', argv: ['npm', 'run', 'test:unit'], command: 'npm run test:unit', timeout_seconds: 180, scenarios: [] },
  { id: 'frontend-typecheck', kind: 'typecheck', argv: ['npx', '--no-install', 'tsc', '-b'], command: 'npx --no-install tsc -b', timeout_seconds: 120, scenarios: [] },
  {
    id: 'project-workflows-browser', kind: 'browser',
    argv: ['npx', '--no-install', 'playwright', 'test', '--config=tests/project-workflows/playwright.config.ts'],
    command: 'npx --no-install playwright test --config=tests/project-workflows/playwright.config.ts', timeout_seconds: 300,
    scenarios: [
      { id: 'review-verdict', description: 'The review node shows the verdict and findings' },
      { id: 'finding-to-task', description: 'A verbatim requirement quote links to the worker task' },
    ],
  },
]
export const ADAPTER_CHECKS: RawCheck[] = [
  { id: 'backend-unit', kind: 'unit', argv: ['npx', '--no-install', 'tsx', '--test', 'server/projects.test.ts'], command: 'npx --no-install tsx --test server/projects.test.ts', timeout_seconds: 180, scenarios: [] },
]
export const DOCS_CHECKS: RawCheck[] = [
  { id: 'docs-unit', kind: 'unit', argv: ['npx', '--no-install', 'tsx', '--test', 'docs/links.test.ts'], command: 'npx --no-install tsx --test docs/links.test.ts', timeout_seconds: 120, scenarios: [] },
]
/** What each lane of the configured policy pins as `required_check_kinds` (policy 1.2.0). */
export const REQUIRED_CHECK_KINDS: Record<string, RawCheck['kind'][]> = { ui: ['build', 'browser'], adapter: ['unit'], docs: ['unit'] }
/** What the adapter derives for a 1.2.0 export, whose policy predates `required_check_kinds`: the verifier's role rule. */
export const roleCheckKinds = (role: string): RawCheck['kind'][] => (role === 'frontend' ? ['build', 'browser'] : ['unit'])

const LANE_INDEX: Record<string, number> = { ui: 1, adapter: 2, docs: 3 }
export const launchToken = (lane: string) => `00000000-0000-4000-8000-00000000000${LANE_INDEX[lane]}`
export const backgroundId = (lane: string) => `1000${LANE_INDEX[lane]}`

function rawWorker(lane: 'ui' | 'adapter', runId: string, leak: string, requestedAt: string): RawWorkerInput {
  const ui = lane === 'ui'
  const failedAdapter = !ui && runId === RUN_FAILED
  return {
    role: ui ? 'frontend' : 'backend',
    task: ui ? uiTask(leak) : adapterTask(),
    prompt: ui ? uiPrompt(leak) : null,
    owned_paths: ui ? ['src/App.tsx', 'src/App.css', 'src/projects', 'tests/project-workflows'] : ['server', 'config/projects.example.json'],
    checks: ui ? UI_CHECKS : ADAPTER_CHECKS,
    launch: {
      session_id: ui ? UI_SESSION : ADAPTER_SESSION, launch_token: launchToken(lane), launch_requested_at: offset(requestedAt),
      native_started_at: Date.parse(requestedAt) + 2000, observed_state: failedAdapter ? 'working' : 'done', status: 'attached_session_available',
      launcher_invocations: 1, background_id: backgroundId(lane),
    },
    completion: failedAdapter ? null : ui
      ? { status: 'completed', summary: uiCompletionSummary(leak), open_assumptions: [UI_ASSUMPTION] }
      : { status: 'completed', summary: ADAPTER_COMPLETION_SUMMARY, open_assumptions: [] },
    // The UI handoff repeats the completion; the adapter's was amended when it was accepted, so it differs.
    handoff: failedAdapter ? null : ui
      ? { summary: uiCompletionSummary(leak), open_assumptions: [UI_ASSUMPTION] }
      : { summary: ADAPTER_HANDOFF_SUMMARY, open_assumptions: [ADAPTER_HANDOFF_ASSUMPTION] },
    stop: failedAdapter ? { stopped: false, confirmed_at: null } : { stopped: true, confirmed_at: offset(T2) },
  }
}

function rawDocsWorker(requestedAt: string): RawWorkerInput {
  return {
    role: 'writer',
    task: docsTask(),
    prompt: null,
    owned_paths: ['docs', 'features/project-workflows/README.md'],
    checks: DOCS_CHECKS,
    launch: {
      session_id: DOCS_SESSION, launch_token: launchToken('docs'), launch_requested_at: offset(requestedAt),
      native_started_at: Date.parse(requestedAt) + 2000, observed_state: 'done', status: 'attached_session_available',
      launcher_invocations: 1, background_id: backgroundId('docs'),
    },
    completion: { status: 'completed', summary: DOCS_COMPLETION_SUMMARY, open_assumptions: [] },
    handoff: { summary: DOCS_COMPLETION_SUMMARY, open_assumptions: [] },
    stop: { stopped: true, confirmed_at: offset(T2) },
  }
}

/** A lane of a 1.3.0 export: the same receipts as before plus the lane's pinned `required_check_kinds`. */
function rawLaneWorker(lane: string, runId: string, leak: string, requestedAt: string): RawWorkerInput {
  const base = lane === 'docs' ? rawDocsWorker(requestedAt) : rawWorker(lane as 'ui' | 'adapter', runId, leak, requestedAt)
  return { ...base, required_check_kinds: REQUIRED_CHECK_KINDS[lane] }
}

/** The export's `inputs` section for a run, or null for the legacy export that predates it. */
export function rawInputsSection(runId: string, leak = PATH_TOKEN): RawInputsSection | null {
  if (runId === RUN_LEGACY) return null
  if (runId === RUN_TWO_REVIEWERS || runId === RUN_REVIEWER_BLOCKED || runId === RUN_LEGACY_REVIEWER) {
    // The reviewers workflow's lanes are pinned like any configured policy's; the reviewer set lives in the review section, not here.
    return {
      feature: REVIEWERS_FEATURE_NAME, policy_version: '1.2.0', base_commit: BASE_COMMIT, source_branch: sourceBranch(runId, REVIEWERS_WORKFLOW_ID),
      mode: 'automatic',
      automatic: { finish: 'verified-feature-branch', permission_mode: 'bypassPermissions', worker_timeout_seconds: 7200, review_timeout_seconds: 1800, reviewer_transport: 'native' },
      setup: [{ argv: ['npm', 'ci'], command: 'npm ci', timeout_seconds: 600 }],
      max_verification_attempts: 3,
      failure_drill: null,
      selected_workers: [...TWO_LANES],
      excluded_workers: [],
      workers: Object.fromEntries(TWO_LANES.map(lane => [lane, rawLaneWorker(lane, runId, leak, T1)])),
    }
  }
  if (runId === RUN_THREE_LANES || runId === RUN_ONE_LANE) {
    const selected: readonly string[] = runId === RUN_THREE_LANES ? THREE_LANES : ONE_LANE
    return {
      feature: LANES_FEATURE_NAME, policy_version: '1.2.0', base_commit: BASE_COMMIT, source_branch: sourceBranch(runId, LANES_WORKFLOW_ID),
      mode: 'automatic',
      automatic: { finish: 'verified-feature-branch', permission_mode: 'bypassPermissions', worker_timeout_seconds: 7200, review_timeout_seconds: 1800, reviewer_transport: 'native' },
      setup: [{ argv: ['npm', 'ci'], command: 'npm ci', timeout_seconds: 600 }],
      max_verification_attempts: 3,
      // The policy's drill names the adapter lane; the one-lane run did not select it, so the drill was skipped.
      failure_drill: { node_id: 'adapter', phase: 'worker', attempt: 2 },
      selected_workers: [...selected],
      excluded_workers: THREE_LANES.filter(lane => !selected.includes(lane)),
      workers: Object.fromEntries(selected.map(lane => [lane, rawLaneWorker(lane, runId, leak, T1)])),
    }
  }
  const requestedAt = runId === RUN_SUCCEEDED ? T0 : runId === RUN_AWAITING ? T2 : T1
  const manual = runId === RUN_AWAITING
  return {
    feature: FEATURE_NAME, policy_version: '1.1.0', base_commit: BASE_COMMIT, source_branch: sourceBranch(runId),
    mode: manual ? 'manual' : 'automatic',
    automatic: manual ? null : {
      finish: 'verified-feature-branch', permission_mode: 'bypassPermissions',
      worker_timeout_seconds: runId === RUN_SUCCEEDED ? 14400 : 3600, review_timeout_seconds: 1800,
      // The failed run was pinned before the setting existed and never reviewed: the export records null, never a guess.
      reviewer_transport: runId === RUN_BLOCKED ? 'print' : runId === RUN_FAILED ? null : 'native',
    },
    setup: [{ argv: ['npm', 'ci'], command: 'npm ci', timeout_seconds: 600 }],
    max_verification_attempts: 3,
    failure_drill: runId === RUN_FAILED ? { node_id: 'adapter', phase: 'worker', attempt: 1 } : null,
    workers: { ui: rawWorker('ui', runId, leak, requestedAt), adapter: rawWorker('adapter', runId, leak, requestedAt) },
  }
}

// ---- Projections onto the contract (what the mocks serve) ----------------------------------------------

/** The lanes (in policy order) whose task text contains the quote verbatim; the same rule the adapter applies. */
function lanesQuoting(requirement: string | null, tasks: Record<string, string>): string[] {
  if (requirement === null) return []
  return Object.keys(tasks).filter(lane => tasks[lane].includes(requirement))
}

/**
 * The review projection at contract 1.4.0. A section without `reviewers` (exports before 1.4.0) is one reviewer named
 * `review`: the adapter fills a one-entry list from the section itself and tags every finding with that id, so the viewer
 * has a single code path. The combined `reviewer` identity stays what the review node names (the first reviewer's session).
 */
function projectReview(runId: string, section: RawReviewSection, tasks: Record<string, string>): ReviewResult {
  const link = (finding: RawFinding, reviewer: string) => ({ ...finding, reviewer: finding.reviewer ?? reviewer, requirement_found_in: lanesQuoting(finding.requirement, tasks) })
  const reviewers: RawReviewer[] = section.reviewers ?? [{
    reviewer_id: DEFAULT_REVIEWER_ID, transport: section.transport, session_id: section.reviewer_session_id, verdict: section.verdict,
    findings: section.findings, launched_at: null, accepted_at: section.reviewed_at, status: section.verdict === 'approved' ? 'accepted' : 'blocked',
  }]
  return validateReviewResult({
    contract_version: REVIEW_CONTRACT_VERSION, run_id: runId, node_id: 'review', attempt: section.attempt,
    reviewer: { session_id: section.reviewer_session_id, transport: section.transport, independent: true },
    bundle_sha256: section.bundle_sha256, candidate_commit: section.candidate_commit, verdict: section.verdict,
    findings: section.findings.map(finding => link(finding, DEFAULT_REVIEWER_ID)),
    reviewers: reviewers.map(reviewer => ({
      reviewer_id: reviewer.reviewer_id, transport: reviewer.transport, session_id: reviewer.session_id, verdict: reviewer.verdict,
      findings: reviewer.findings.map(finding => link(finding, reviewer.reviewer_id)),
      launched_at: reviewer.launched_at === null ? null : zulu(reviewer.launched_at),
      accepted_at: reviewer.accepted_at === null ? null : zulu(reviewer.accepted_at),
      status: reviewer.status,
    })),
    reviewed_at: zulu(section.reviewed_at),
    diff: section.diff === null ? null : { artifact_id: REVIEW_DIFF_ARTIFACT_ID, kind: 'patch', uri: `${apiRunPath(runId, runDetails[runId].summary.workflow_id)}/artifacts/${REVIEW_DIFF_ARTIFACT_ID}`, sha256: section.diff.sha256 },
  })
}

/**
 * The run-inputs projection at the current contract. A 1.2.0 export has neither a selection nor pinned check kinds: every
 * listed lane was selected, nothing was excluded, and the kinds are the ones its role required, exactly as the adapter serves it.
 */
function projectInputs(runId: string, section: RawInputsSection): RunInputs {
  return validateRunInputs({
    contract_version: INPUTS_CONTRACT_VERSION, run_id: runId, feature: section.feature, base_commit: section.base_commit, source_branch: section.source_branch,
    mode: section.mode, automatic: section.automatic,
    setup: section.setup.map(step => ({ command: step.command, timeout_seconds: step.timeout_seconds })),
    max_verification_attempts: section.max_verification_attempts,
    selected_workers: section.selected_workers ?? Object.keys(section.workers),
    excluded_workers: section.excluded_workers ?? [],
    workers: Object.entries(section.workers).map(([lane, worker]) => {
      return {
        node_id: lane, launch_node_id: `launch_${lane}`, role: worker.role,
        required_check_kinds: worker.required_check_kinds ?? roleCheckKinds(worker.role),
        task: { text: worker.task, truncated: false },
        prompt: worker.prompt === null ? null : { text: worker.prompt, truncated: false },
        owned_paths: worker.owned_paths,
        checks: worker.checks.map(({ id, kind, command, timeout_seconds, scenarios }) => ({ id, kind, command, timeout_seconds, scenarios })),
        launch: worker.launch === null ? null : {
          session_id: worker.launch.session_id, launch_requested_at: zulu(worker.launch.launch_requested_at),
          native_started_at: worker.launch.native_started_at === null ? null : new Date(worker.launch.native_started_at).toISOString(),
          observed_state: worker.launch.observed_state, status: worker.launch.status, launcher_invocations: worker.launch.launcher_invocations,

    The default reviewer keeps today's single file: its own keys (launch token, session, decision) are
    merged into `automatic-review.json`, whose combined `status` wins. Declared reviewers each get
    `automatic-review-<id>.json` beside the combined file.
    """

    def __init__(self, runtime, combined: dict, statuses: dict):
        self.runtime, self.combined, self.statuses = runtime, combined, statuses
        # Accepted decisions live here until the combined decision persists them (or a deadline/rejection retains them).
        self.decisions: dict = {}

    @property
    def ids(self) -> list[str]:
        return list(self.statuses)

    @classmethod
    def load(cls, runtime) -> "ReviewStatus":
        combined = read_json(combined_status_path(runtime))
        ids = combined.get("reviewers") or reviewer_ids(runtime.plan)
        statuses = {}
        for reviewer_id in ids:
            path = reviewer_status_path(runtime, reviewer_id)
            statuses[reviewer_id] = read_json(path) if path.exists() else {"reviewer_id": reviewer_id, "node_id": review_node(reviewer_id), "status": "pending"}
        return cls(runtime, combined, statuses)

    def save(self) -> None:
        merged = {}
        for reviewer_id, status in self.statuses.items():
            path = reviewer_status_path(self.runtime, reviewer_id)
            if path == combined_status_path(self.runtime):
                merged = status
            else:
                save_json(path, status)
        save_json(combined_status_path(self.runtime), {**merged, **self.combined})

    def record_decisions(self) -> None:
        for reviewer_id, decision in self.decisions.items():
            self.statuses[reviewer_id]["decision"] = decision

    def supersede_running(self) -> None:
        """A reviewer still working when the run is decided is stopped; its status records why nothing waited for it."""
        for status in self.statuses.values():
            if status.get("status") in {"pending", "launching", "running"}:
                status["status"] = "superseded"


def read_review_completion(runtime, reviewer_id: str = DEFAULT_REVIEWER) -> dict:
    """Accept a reviewer's file only when it validates and is bound to this exact run, reviewer, launch, bundle and candidate."""
    from jsonschema.exceptions import ValidationError
    from .verification import validate_schema
    node = review_node(reviewer_id)
    path = runtime.directory / f"{node}.completion.json"
    if path.is_symlink() or not path.is_file() or path.stat().st_size > REVIEW_COMPLETION_LIMIT:
        raise RuntimeError(f"Invalid review completion file ({reviewer_id})")
    try:
        item = read_json(path)
    except ValueError as error:
        raise RuntimeError(f"Malformed review completion signal ({reviewer_id}): {error}") from None
    try:
        validate_schema("reviewCompletion", item)
    except ValidationError as error:
        raise RuntimeError(f"Review completion signal ({reviewer_id}) violates the schema: {error.message}") from None
    status = read_json(reviewer_status_path(runtime, reviewer_id))
    bundle, digest = runtime.validate_bundle()
    if (item["run_id"] != runtime.plan["run_id"] or item["node_id"] != node or item["launch_token"] != status.get("launch_token")
            or item["bundle_sha256"] != digest or item["candidate_commit"] != bundle["candidate_commit"]):
        raise RuntimeError(f"Stale or foreign review completion signal ({reviewer_id})")
    check_finding_lanes(runtime, item["findings"])
    return {"verdict": item["verdict"], "findings": item["findings"]}


def decision_blocks(decision: dict) -> bool:
    """A blocked verdict or an unresolved P0/P1 from any one reviewer blocks the run."""
    from .pipeline import blocking_findings
    return decision["verdict"] != "approved" or bool(blocking_findings(decision["findings"]))


def wait_reviews(runtime, state: ReviewStatus | None = None, *, clock=None, sleep=None) -> dict:
    """Poll every reviewer's receipt. Idle alone never means a verdict; each deadline counts from that reviewer's own launch.

    Returns the accepted decisions by reviewer id (also kept in `state.decisions`) as soon as every reviewer approved,
    or as soon as one accepted file blocks (the others are not waited for). A rejected file, an expired deadline or
    a missing session raises.
    """
    clock = clock or time.time
    sleep = sleep or time.sleep
    validate_automatic(runtime.plan)
    state = state or ReviewStatus.load(runtime)
    timeout = runtime.plan["automatic"]["review_timeout_seconds"]
    started = {}
    for reviewer_id in state.ids:
        receipt = read_json(runtime.directory / f"{review_node(reviewer_id)}.interactive.json")
        started[reviewer_id] = datetime.fromisoformat(receipt["launch_requested_at"]).timestamp()
    decisions = state.decisions
    attention = set()
    while True:
        rows = runtime.sessions.inventory()
        for reviewer_id in state.ids:
            if reviewer_id in decisions:
                continue
            node = review_node(reviewer_id)
            status = state.statuses[reviewer_id]
            if clock() >= started[reviewer_id] + timeout:
                status.update(status="blocked", error="Reviewer deadline exhausted; no second reviewer is launched")
                state.save()
                raise RuntimeError(f"Reviewer {reviewer_id} deadline exhausted; no second reviewer is launched")
            row = runtime.sessions.locate(node, rows)
            if row is None:
                raise RuntimeError(f"Native reviewer {reviewer_id} missing; reconciliation required")
            if row["state"] == "blocked" and reviewer_id not in attention:
                # A native session reports `blocked` when it needs a human: a question or a prompt
                # it cannot answer itself. The operator may answer in the pane; the deadline bounds it.
                attention.add(reviewer_id)
                runtime.event("review", "interactive", f"Reviewer {reviewer_id} needs attention in its pane (native state blocked); waiting until the deadline")
            if row["state"] in {"idle", "done"} and (runtime.directory / f"{node}.completion.json").exists():
                try:
                    decision = read_review_completion(runtime, reviewer_id)
                except RuntimeError as error:
                    status.update(status="blocked", error=str(error))
                    state.save()
                    raise
                decisions[reviewer_id] = decision
                status.update(status="accepted", accepted_at=now())
                state.save()
                if decision_blocks(decision):
                    return decisions  # The first block decides; nobody waits for the other reviewers.
        if set(decisions) == set(state.ids):
            return decisions
        sleep(2)

/**
 * Helpers shared by the Projects viewer specs: URL builders, locators for the run view, the screenshot
 * attachment every scenario records, the per-test setup (isolated API up, mocks in worker mode) and the
 * redaction assertion used by the `paths-redacted` scenarios.
 */
import { test, expect, type APIRequestContext, type Locator, type Page, type TestInfo } from '@playwright/test'
import { waitForApi } from '../helpers.ts'
import { apiRunPath, PROJECT, WORKFLOW_ID } from './fixtures.ts'
import { verificationPhase } from './harness.ts'
import { installProjectMocks } from './mock.ts'

export const phase = verificationPhase()

export const projectsUrl = '/projects'
export const projectUrl = (projectId: string) => `/projects/${encodeURIComponent(projectId)}`
export const workflowUrl = (projectId: string, workflowId: string) => `${projectUrl(projectId)}/workflows/${encodeURIComponent(workflowId)}`
export const runUrl = (runId: string, nodeId?: string, workflowId: string = WORKFLOW_ID) => `${workflowUrl(PROJECT.project_id, workflowId)}/runs/${encodeURIComponent(runId)}${nodeId ? `/nodes/${encodeURIComponent(nodeId)}` : ''}`
export const apiRun = apiRunPath

export const workspace = (page: Page) => page.getByTestId('projects-workspace')
export const graphNode = (page: Page, nodeId: string) => page.locator(`[data-testid="workflow-graph"] [data-graph-node="${nodeId}"]`)
export const nodeListItem = (page: Page, nodeId: string) => page.locator(`[data-testid="run-node-list"] [data-node-id="${nodeId}"]`)
export const nodeDetail = (page: Page) => page.getByTestId('node-detail')

/** No view action may launch, approve, retry, delete or edit a run: no such real controls exist (graph nodes are read-only selectors). */
export async function expectNoExecutionControls(page: Page) {
  const controls = workspace(page).locator('button, input, select, textarea, [role="menuitem"]')
  await expect(controls.filter({ hasText: /approve|retry|launch|start|resume|delete|cancel|integrate|edit|save/i })).toHaveCount(0)
  await expect(page.locator('form')).toHaveCount(0)
}

export async function attach(page: Page, testInfo: TestInfo, id: string) {
  const image = testInfo.outputPath(`${id}.png`)
  await page.screenshot({ path: image, fullPage: true })
  await testInfo.attach(`screenshot:${id}`, { path: image, contentType: 'image/png' })
}

export async function waitForProjectsApi(request: APIRequestContext) {
  if (phase !== 'candidate') return
  await expect.poll(async () => (await request.get('/api/projects')).status(), { timeout: 30_000 }).toBe(200)
}

/** Registers the suite's shared per-test setup; call once at the top level of a spec file. */
export function installHooks() {
  test.beforeEach(async ({ page, request }) => {
    await waitForApi(request)
    await waitForProjectsApi(request)
    if (phase === 'worker') await installProjectMocks(page)
  })
}

/** Reads the rendered text and asserts no absolute filesystem path (temporary root or home) leaked into it. */
export async function renderedText(locator: Locator): Promise<string> {
  const text = await locator.innerText()
  expect(text, 'rendered text must not name a temporary or home directory').not.toMatch(/\/tmp\/|\/home\//)
  return text
}

/** Fetches a URL from inside the page, so worker-mode route mocks apply exactly as they do for the app. */
export async function fetchFromPage(page: Page, url: string): Promise<{ status: number; contentType: string | null; text: string }> {
  return page.evaluate(async target => {
    const response = await fetch(target)
    return { status: response.status, contentType: response.headers.get('content-type'), text: await response.text() }
  }, url)
}
